const MOD = 998244353;
const N = 5000;

function mulmod(a, b) {
  const ah = Math.floor(a / 65536), al = a % 65536;
  return ((ah * b % MOD) * 65536 + al * b) % MOD;
}

const factor = new Array(N + 1);
let primes = [];

function comb(m, n) {
  let res = 1;
  const fnm = new Int32Array(primes.length);
  fnm.set(factor[n]);
  const fm = factor[m];
  for (let i = 0; i < fm.length; i++) {
    fnm[i] += fm[i];
  }
  for (let w = 1; w <= m; w++) {
    let r = 1;
    const fw = factor[w], fnw = factor[n - w], fmw = factor[m - w];
    for (let i = 0; i < primes.length; i++) {
      let p = primes[i];
      for (let pw = fnm[i] - fw[i] - fnw[i] - fmw[i]; pw > 0; pw >>= 1) {
        if ((pw & 1) === 1) {
          r = mulmod(r, p);
        }
        p = mulmod(p, p);
      }
    }
    res += r;
  }
  return res % MOD;
}

function main() {
  const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);
  const abc = [parseInt(data[0], 10), parseInt(data[1], 10), parseInt(data[2], 10)];
  abc.sort((x, y) => x - y);

  const sieve = new Array(N + 1).fill(false);
  sieve[0] = true;
  sieve[1] = true;
  for (let p = 0; p <= N; p++) {
    if (!sieve[p]) {
      primes.push(p);
      for (let q = p * p; q <= N; q += p) {
        sieve[q] = true;
      }
    }
  }

  for (let j = 0; j <= N; j++) {
    factor[j] = new Int32Array(primes.length);
  }
  for (let i = 0; i < primes.length; i++) {
    const p = primes[i];
    for (let pp = p; pp <= N; pp *= p) {
      for (let j = pp; j <= N; j += pp) {
        factor[j][i]++;
      }
    }
  }

  let a = factor[0];
  for (let j = 0; j <= N; j++) {
    const b = factor[j];
    for (let i = 0; i < a.length; i++) {
      b[i] += a[i];
    }
    a = b;
  }

  const ans = mulmod(mulmod(comb(abc[0], abc[1]), comb(abc[0], abc[2])), comb(abc[1], abc[2]));
  console.log(ans);
}

main();
